 "content": "from collections import Counter


def transform(grid):
    """Fill the spaces between aligned, identical non-background markers."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # In each row, bridge consecutive markers of the same color.
    for r in range(h):
        by_color = {}
        for c, value in enumerate(grid[r]):
            if value != background:
                by_color.setdefault(value, []).append(c)
        for positions in by_color.values():
            for left, right in zip(positions, positions[1:]):
                for c in range(left + 1, right):
                    if grid[r][c] == background:
                        out[r][c] = 3

    # In each column, bridge consecutive markers of the same color.
    for c in range(w):
        by_color = {}
        for r in range(h):
            value = grid[r][c]
            if value != background:
                by_color.setdefault(value, []).append(r)
        for positions in by_color.values():
            for top, bottom in zip(positions, positions[1:]):
                for r in range(top + 1, bottom):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
